// DEV_RIO_102 Experiment Design — 実運用
// DEV_RIO_101のevidence_pack（theme/audience/facts）を受け取る。未指定時のみデフォルト値を使う。
const i = $input.first().json;
return [{ json: {
  experiment_id: i.experiment_id ?? 'exp-001',
  theme: i.theme ?? '店舗の固定費/決済手数料の見直し',
  audience: i.audience ?? '小規模店舗経営者(飲食・美容)',
  facts: i.facts ?? [],
  judge_by: i.judge_by ?? null
} }];

// 単一変数の成長実験を1件設計させるプロンプトを組み立てる。
const i = $input.first().json;
const factsText = (i.facts && i.facts.length) ? i.facts.map(f => `- ${f.claim}`).join('\n') : '（参考情報なし）';
const prompt = `あなたは growth marketer です。以下の情報から、単一変数のみを変える成長実験を1つ設計してください（A/Bテストの片側案ではなく、次に試す1実験）。

テーマ: ${i.theme}
想定読者: ${i.audience}
参考情報:
${factsText}

出力は必ず次のJSON形式のみで返してください（説明文・コードブロック記号なし）。
{
  "audience_id": "string(半角英数とハイフンのみ)",
  "offer_id": "string",
  "angle": "string(訴求の切り口。日本語1文)",
  "channel": "threads/note/x/instagram のいずれか",
  "variable_changed": "hook/format/cta/timing のいずれか1つのみ",
  "success_condition": "測定可能な成功条件(日本語)",
  "stop_condition": "測定可能な停止条件(日本語)",
  "min_data": "最低必要データ量(日本語)"
}

注意:
- variable_changed は必ず1つだけ選ぶこと（複数指定・カンマ区切り禁止）。
- "必ず売れる"等の断定的な成果予測を書かないこと。`;
const anthropic_body = {
  model: 'claude-sonnet-4-5',
  max_tokens: 512,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, design_prompt: prompt, anthropic_body } }];

// Anthropicの応答をパース。失敗時はデフォルト値にフォールバックし、design_sourceで明示する（捏造しない）。
const input = $input.first().json;
const o = $('Build Experiment Design Prompt').first().json;
let design = null;
let design_error = null;

if (input.error) {
  design_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    design = JSON.parse(cleaned);
  } catch (e) {
    design_error = 'parse_failed: ' + e.message;
  }
}

const fallback = {
  audience_id: 'aud-store-owner',
  offer_id: 'P-BRAIN-01',
  angle: 'AIで雑務を週3時間削減',
  channel: 'threads',
  variable_changed: 'hook',
  success_condition: 'note遷移≥50 かつ Brain遷移≥5（14日）',
  stop_condition: '≥1000表示 or ≥50クリックで明確な負',
  min_data: '≥1000表示 or ≥50クリック'
};
const d = design || {};

return [{ json: {
  experiment_id: o.experiment_id,
  audience_id: d.audience_id ?? fallback.audience_id,
  offer_id: d.offer_id ?? fallback.offer_id,
  angle: d.angle ?? fallback.angle,
  channel: d.channel ?? fallback.channel,
  variable_changed: d.variable_changed ?? fallback.variable_changed,
  success_condition: d.success_condition ?? fallback.success_condition,
  stop_condition: d.stop_condition ?? fallback.stop_condition,
  min_data: d.min_data ?? fallback.min_data,
  judge_by: o.judge_by ?? null,
  design_source: design ? 'anthropic_ai' : 'fallback_default',
  design_error
} }];

// バリデーション: 変更変数が1つか、必須項目が揃っているか。
const o = $input.first().json;
const required = ['experiment_id','audience_id','offer_id','channel','variable_changed','success_condition','stop_condition'];
const missing = required.filter(k => !o[k]);
const singleVariable = typeof o.variable_changed === 'string' && !o.variable_changed.includes(',');
const valid = missing.length === 0 && singleVariable;
return [{ json: { ...o, valid, missing, singleVariable, state: valid ? 'QA_REVIEW' : 'FAILED_RETRYABLE',
  note: valid ? `experiments へ登録候補（設計元: ${o.design_source}）` : `不備: ${missing.join(',') || '変更変数が複数'}` } }];
